1	import { useState, useCallback } from "react";
2	import { useNavigate } from "react-router-dom";
3	import { useDebounce } from "@/hooks/use-debounce";
4	import {
5	  Search,
6	  Users as UsersIcon,
7	  ChevronUp,
8	  ChevronDown,
9	  ChevronsUpDown,
10	  ChevronLeft,
11	  ChevronRight,
12	} from "lucide-react";
13	import { PageHeader } from "@/components/shared/PageHeader";
14	import { EmptyState } from "@/components/shared/EmptyState";
15	import { Input } from "@/components/ui/input";
16	import { Button } from "@/components/ui/button";
17	import { Badge } from "@/components/ui/badge";
18	import { Skeleton } from "@/components/ui/skeleton";
19	import {
20	  Select,
21	  SelectContent,
22	  SelectItem,
23	  SelectTrigger,
24	  SelectValue,
25	} from "@/components/ui/select";
26	import {
27	  Table,
28	  TableBody,
29	  TableCell,
30	  TableHead,
31	  TableHeader,
32	  TableRow,
33	} from "@/components/ui/table";
34	import { useAdminUsers, type AdminUsersFilter } from "@/hooks/admin/use-admin-users";
35	import type { ProfileRow } from "@/types/database";
36	import type { PlanType, UserRole } from "@/types/index";
37	import { format } from "date-fns";
38	
39	const PLAN_BADGE_CLASSES: Record<PlanType, string> = {
40	  free: "bg-muted/50 text-foreground/80 border-0",
41	  pro: "bg-indigo-100 text-indigo-700 border-0",
42	  agency: "bg-purple-100 text-purple-700 border-0",
43	};
44	
45	const ROLE_BADGE_CLASSES: Record<UserRole, string> = {
46	  user: "bg-muted/50 text-foreground/80 border-0",
47	  admin: "bg-amber-100 text-amber-700 border-0",
48	  super_admin: "bg-red-100 text-red-700 border-0",
49	};
50	
51	type SortableColumn = "email" | "full_name" | "plan" | "scans_used" | "role" | "created_at";
52	
53	function SortIcon({ column, sortColumn, sortAsc }: {
54	  column: SortableColumn;
55	  sortColumn: SortableColumn;
56	  sortAsc: boolean;
57	}) {
58	  if (sortColumn !== column) return <ChevronsUpDown className="ml-1 h-3.5 w-3.5 text-muted-foreground/40" />;
59	  return sortAsc
60	    ? <ChevronUp className="ml-1 h-3.5 w-3.5 text-primary" />
61	    : <ChevronDown className="ml-1 h-3.5 w-3.5 text-primary" />;
62	}
63	
64	function TableSkeleton() {
65	  return (
66	    <>
67	      {Array.from({ length: 8 }).map((_, i) => (
68	        <TableRow key={i}>
69	          {Array.from({ length: 7 }).map((__, j) => (
70	            <TableCell key={j}>
71	              <Skeleton className="h-4 w-full max-w-[120px]" />
72	            </TableCell>
73	          ))}
74	        </TableRow>
75	      ))}
76	    </>
77	  );
78	}
79	
80	const PAGE_SIZE = 20;
81	
82	function SortableHeader({
83	  column,
84	  label,
85	  sortColumn,
86	  sortAsc,
87	  onSort,
88	}: {
89	  column: SortableColumn;
90	  label: string;
91	  sortColumn: SortableColumn;
92	  sortAsc: boolean;
93	  onSort: (col: SortableColumn) => void;
94	}) {
95	  return (
96	    <TableHead
97	      className="cursor-pointer select-none whitespace-nowrap"
98	      onClick={() => onSort(column)}
99	      aria-sort={
100	        sortColumn === column ? (sortAsc ? "ascending" : "descending") : "none"
101	      }
102	    >
103	      <span className="inline-flex items-center">
104	        {label}
105	        <SortIcon column={column} sortColumn={sortColumn} sortAsc={sortAsc} />
106	      </span>
107	    </TableHead>
108	  );
109	}
110	
111	export default function AdminUsers() {
112	  const navigate = useNavigate();
113	  const [search, setSearch] = useState("");
114	  const [planFilter, setPlanFilter] = useState<PlanType | "">("");
115	  const [roleFilter, setRoleFilter] = useState<UserRole | "">("");
116	  const [page, setPage] = useState(0);
117	  const [sortColumn, setSortColumn] = useState<SortableColumn>("created_at");
118	  const [sortAsc, setSortAsc] = useState(false);
119	
120	  const debouncedSearch = useDebounce(search, 350);
121	
122	  const filter: AdminUsersFilter = {
123	    search: debouncedSearch || undefined,
124	    plan: planFilter || undefined,
125	    role: roleFilter || undefined,
126	  };
127	
128	  const { data, isLoading, isError } = useAdminUsers({
129	    page,
130	    pageSize: PAGE_SIZE,
131	    filter,
132	    sortColumn: sortColumn as keyof ProfileRow,
133	    sortAsc,
134	  });
135	
136	  const totalPages = data ? Math.ceil(data.total / PAGE_SIZE) : 0;
137	
138	  const handleSort = useCallback((col: SortableColumn) => {
139	    setSortColumn((prev) => {
140	      if (prev === col) {
141	        setSortAsc((asc) => !asc);
142	        return prev;
143	      }
144	      setSortAsc(true);
145	      return col;
146	    });
147	    setPage(0);
148	  }, []);
149	
150	  return (
151	    <div className="space-y-6">
152	      <PageHeader
153	        title="Users"
154	        description={
155	          data ? `${data.total.toLocaleString()} total users` : "All registered users"
156	        }
157	      />
158	
159	      {/* Filters */}
160	      <div className="flex flex-wrap items-center gap-3">
161	        <div className="relative flex-1 min-w-[200px] max-w-xs">
162	          <Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
163	          <Input
164	            placeholder="Search by email or name..."
165	            value={search}
166	            onChange={(e) => { setSearch(e.target.value); setPage(0); }}
167	            className="pl-9"
168	            aria-label="Search users"
169	          />
170	        </div>
171	
172	        <Select
173	          value={planFilter}
174	          onValueChange={(v) => {
175	            setPlanFilter(v as PlanType | "");
176	            setPage(0);
177	          }}
178	        >
179	          <SelectTrigger className="w-[130px]" aria-label="Filter by plan">
180	            <SelectValue placeholder="All plans" />
181	          </SelectTrigger>
182	          <SelectContent>
183	            <SelectItem value="">All plans</SelectItem>
184	            <SelectItem value="free">Free</SelectItem>
185	            <SelectItem value="pro">Pro</SelectItem>
186	            <SelectItem value="agency">Agency</SelectItem>
187	          </SelectContent>
188	        </Select>
189	
190	        <Select
191	          value={roleFilter}
192	          onValueChange={(v) => {
193	            setRoleFilter(v as UserRole | "");
194	            setPage(0);
195	          }}
196	        >
197	          <SelectTrigger className="w-[150px]" aria-label="Filter by role">
198	            <SelectValue placeholder="All roles" />
199	          </SelectTrigger>
200	          <SelectContent>
201	            <SelectItem value="">All roles</SelectItem>
202	            <SelectItem value="user">User</SelectItem>
203	            <SelectItem value="admin">Admin</SelectItem>
204	            <SelectItem value="super_admin">Super Admin</SelectItem>
205	          </SelectContent>
206	        </Select>
207	
208	        {(debouncedSearch || planFilter || roleFilter) && (
209	          <Button
210	            variant="ghost"
211	            size="sm"
212	            onClick={() => {
213	              setSearch("");
214	              setDebouncedSearch("");
215	              setPlanFilter("");
216	              setRoleFilter("");
217	              setPage(0);
218	            }}
219	          >
220	            Clear filters
221	          </Button>
222	        )}
223	      </div>
224	
225	      {/* Table */}
226	      <div className="rounded-xl border border-border/50 overflow-hidden overflow-x-auto scrollbar-thin">
227	        <Table>
228	          <TableHeader>
229	            <TableRow className="bg-muted/40 hover:bg-muted/40">
230	              <SortableHeader column="email" label="Email" sortColumn={sortColumn} sortAsc={sortAsc} onSort={handleSort} />
231	              <SortableHeader column="full_name" label="Name" sortColumn={sortColumn} sortAsc={sortAsc} onSort={handleSort} />
232	              <SortableHeader column="plan" label="Plan" sortColumn={sortColumn} sortAsc={sortAsc} onSort={handleSort} />
233	              <SortableHeader column="scans_used" label="Scans Used" sortColumn={sortColumn} sortAsc={sortAsc} onSort={handleSort} />
234	              <SortableHeader column="role" label="Role" sortColumn={sortColumn} sortAsc={sortAsc} onSort={handleSort} />
235	              <SortableHeader column="created_at" label="Signed Up" sortColumn={sortColumn} sortAsc={sortAsc} onSort={handleSort} />
236	              <TableHead className="w-10" />
237	            </TableRow>
238	          </TableHeader>
239	          <TableBody>
240	            {isLoading ? (
241	              <TableSkeleton />
242	            ) : isError ? (
243	              <TableRow>
244	                <TableCell
245	                  colSpan={7}
246	                  className="py-10 text-center text-sm text-red-600"
247	                >
248	                  Failed to load users. Check your admin permissions.
249	                </TableCell>
250	              </TableRow>
251	            ) : data?.users.length === 0 ? (
252	              <TableRow>
253	                <TableCell colSpan={7} className="p-0">
254	                  <EmptyState
255	                    icon={UsersIcon}
256	                    title="No users found"
257	                    description="Try adjusting your search or filters."
258	                  />
259	                </TableCell>
260	              </TableRow>
261	            ) : (
262	              data?.users.map((user) => (
263	                <TableRow
264	                  key={user.id}
265	                  className="cursor-pointer hover:bg-muted/40 transition-colors"
266	                  onClick={() => navigate(`/admin/users/${user.id}`)}
267	                  aria-label={`View user ${user.email}`}
268	                >
269	                  <TableCell className="font-mono text-xs text-muted-foreground">
270	                    {user.email}
271	                  </TableCell>
272	                  <TableCell className="text-sm font-medium">
273	                    <div className="flex items-center gap-1.5">
274	                      {user.full_name || (
275	                        <span className="text-muted-foreground/50">—</span>
276	                      )}
277	                      {user.is_banned && (
278	                        <Badge className="bg-red-100 text-red-700 border-0 text-[10px] px-1.5 py-0">
279	                          Banned
280	                        </Badge>
281	                      )}
282	                    </div>
283	                  </TableCell>
284	                  <TableCell>
285	                    <Badge
286	                      className={`text-[11px] px-2 py-0.5 capitalize ${
287	                        PLAN_BADGE_CLASSES[user.plan]
288	                      }`}
289	                    >
290	                      {user.plan}
291	                    </Badge>
292	                  </TableCell>
293	                  <TableCell className="text-sm text-muted-foreground">
294	                    {user.scans_used} / {user.scan_limit}
295	                  </TableCell>
296	                  <TableCell>
297	                    <Badge
298	                      className={`text-[11px] px-2 py-0.5 capitalize ${
299	                        ROLE_BADGE_CLASSES[user.role]
300	                      }`}
301	                    >
302	                      {user.role.replace("_", " ")}
303	                    </Badge>
304	                  </TableCell>
305	                  <TableCell className="text-sm text-muted-foreground">
306	                    {format(new Date(user.created_at), "MMM d, yyyy")}
307	                  </TableCell>
308	                  <TableCell>
309	                    <ChevronRight className="h-4 w-4 text-muted-foreground/40" />
310	                  </TableCell>
311	                </TableRow>
312	              ))
313	            )}
314	          </TableBody>
315	        </Table>
316	      </div>
317	
318	      {/* Pagination */}
319	      {totalPages > 1 && (
320	        <div className="flex items-center justify-between">
321	          <p className="text-sm text-muted-foreground">
322	            Page {page + 1} of {totalPages} ({data?.total.toLocaleString()} users)
323	          </p>
324	          <div className="flex items-center gap-2">
325	            <Button
326	              variant="outline"
327	              size="sm"
328	              onClick={() => setPage((p) => Math.max(0, p - 1))}
329	              disabled={page === 0}
330	              aria-label="Previous page"
331	            >
332	              <ChevronLeft className="h-4 w-4" />
333	            </Button>
334	            <Button
335	              variant="outline"
336	              size="sm"
337	              onClick={() => setPage((p) => Math.min(totalPages - 1, p + 1))}
338	              disabled={page >= totalPages - 1}
339	              aria-label="Next page"
340	            >
341	              <ChevronRight className="h-4 w-4" />
342	            </Button>
343	          </div>
344	        </div>
345	      )}
346	    </div>
347	  );
348	}
