63	} from "@/hooks/admin/use-admin-scans";
64	import type { ScanRow } from "@/types/database";
65	import type { ScanStatus } from "@/types/index";
66	import { format } from "date-fns";
67	
68	// ── Constants ─────────────────────────────────────────────────
69	
70	const PAGE_SIZE = 25;
71	
72	const STATUS_OPTIONS: { value: ScanStatus | ""; label: string }[] = [
73	  { value: "", label: "All statuses" },
74	  { value: "pending", label: "Pending" },
75	  { value: "analyzing", label: "Analyzing" },
76	  { value: "completed", label: "Completed" },
77	  { value: "failed", label: "Failed" },
78	];
79	
80	const STATUS_BADGE_CLASSES: Record<ScanStatus, string> = {
81	  completed: "bg-green-100 text-green-700 border-0",
82	  failed: "bg-red-100 text-red-700 border-0",
83	  pending: "bg-muted/50 text-foreground/80 border-0",
84	  analyzing: "bg-blue-100 text-blue-700 border-0",
85	};
86	
87	const STATUS_ICONS: Record<ScanStatus, React.ElementType> = {
88	  completed: CheckCircle2,
89	  failed: AlertTriangle,
90	  pending: Clock,
91	  analyzing: Loader2,
92	};
93	
94	type SortableColumn = "created_at" | "overall_score" | "issues_found" | "url" | "status";
95	
96	// ── Sub-components ────────────────────────────────────────────
97	
98	function StatsSkeleton() {
99	  return (
100	    <div className="grid grid-cols-2 gap-4 lg:grid-cols-4">
101	      {Array.from({ length: 4 }).map((_, i) => (
102	        <Skeleton key={i} className="h-[120px] rounded-xl" />
103	      ))}
104	    </div>
105	  );
106	}
107	
108	function TableSkeleton() {
109	  return (
110	    <>
111	      {Array.from({ length: 8 }).map((_, i) => (
112	        <TableRow key={i}>
113	          {Array.from({ length: 8 }).map((__, j) => (
114	            <TableCell key={j}>
115	              <Skeleton className="h-4 w-full max-w-[120px]" />
116	            </TableCell>
117	          ))}
118	        </TableRow>
119	      ))}
120	    </>
121	  );
122	}
123	
124	function SortIcon({
125	  column,
126	  sortColumn,
127	  sortAsc,
128	}: {
129	  column: SortableColumn;
130	  sortColumn: SortableColumn;
131	  sortAsc: boolean;
132	}) {
133	  if (sortColumn !== column)
134	    return <ChevronsUpDown className="ml-1 h-3.5 w-3.5 text-muted-foreground/40" />;
135	  return sortAsc ? (
136	    <ChevronUp className="ml-1 h-3.5 w-3.5 text-primary" />
137	  ) : (
138	    <ChevronDown className="ml-1 h-3.5 w-3.5 text-primary" />
139	  );
140	}
141	
142	function ScoreDisplay({ score }: { score: number | null }) {
143	  if (score === null) return <span className="text-muted-foreground/50">—</span>;
144	  const color =
145	    score >= 75
146	      ? "text-green-600"
147	      : score >= 50
148	      ? "text-amber-600"
149	      : "text-red-600";
150	  return (
151	    <span className={`font-semibold tabular-nums ${color}`}>{score}</span>
152	  );
153	}
154	
155	// ── SortableHeader ────────────────────────────────────────────
156	
157	function SortableHeader({
158	  column,
159	  label,
160	  className,
161	  sortColumn,
162	  sortAsc,
163	  onSort,
164	}: {
165	  column: SortableColumn;
166	  label: string;
167	  className?: string;
168	  sortColumn: SortableColumn;
169	  sortAsc: boolean;
170	  onSort: (col: SortableColumn) => void;
171	}) {
172	  return (
173	    <TableHead
174	      className={`cursor-pointer select-none whitespace-nowrap ${className ?? ""}`}
175	      onClick={() => onSort(column)}
176	      aria-sort={
177	        sortColumn === column ? (sortAsc ? "ascending" : "descending") : "none"
178	      }
179	    >
180	      <span className="inline-flex items-center">
181	        {label}
182	        <SortIcon column={column} sortColumn={sortColumn} sortAsc={sortAsc} />
183	      </span>
184	    </TableHead>
185	  );
186	}
187	
188	// ── Main page ─────────────────────────────────────────────────
189	
190	export default function AdminScans() {
191	  const [search, setSearch] = useState("");
192	  const [statusFilter, setStatusFilter] = useState<ScanStatus | "">("");
193	  const [page, setPage] = useState(0);
194	  const [sortColumn, setSortColumn] = useState<SortableColumn>("created_at");
195	  const [sortAsc, setSortAsc] = useState(false);
196	  const [deleteTarget, setDeleteTarget] = useState<{ id: string; url: string } | null>(null);
197	
198	  const debouncedSearch = useDebounce(search, 350);
199	
200	  const filter: AdminScansFilter = {
201	    search: debouncedSearch || undefined,
202	    status: statusFilter || undefined,
203	  };
204	
205	  const { data, isLoading, isError } = useAdminScans({
206	    page,
207	    pageSize: PAGE_SIZE,
208	    filter,
209	    sortColumn: sortColumn as keyof ScanRow,
210	    sortAsc,
211	  });
212	
213	  const statsQuery = useAdminScanStats();
214	  const deleteScan = useDeleteScan();
215	
216	  const totalPages = data ? Math.ceil(data.total / PAGE_SIZE) : 0;
217	
218	  const handleSort = useCallback((col: SortableColumn) => {
219	    setSortColumn((prev) => {
220	      if (prev === col) {
221	        setSortAsc((asc) => !asc);
222	        return prev;
223	      }
224	      setSortAsc(true);
225	      return col;
226	    });
227	    setPage(0);
228	  }, []);
229	
230	  const hasFilters = debouncedSearch || statusFilter;
231	
232	  return (
233	    <div className="space-y-8">
234	      <PageHeader
235	        title="All Scans"
236	        description={
237	          data
238	            ? `${data.total.toLocaleString()} scans across all users`
239	            : "Platform-wide scan overview"
240	        }
241	      />
242	
243	      {/* KPI row */}
244	      {statsQuery.isLoading ? (
245	        <StatsSkeleton />
246	      ) : statsQuery.isError ? (
247	        <div
248	          role="alert"
249	          className="rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-700"
250	        >
251	          Failed to load scan stats.
252	        </div>
253	      ) : (
254	        <div className="grid grid-cols-2 gap-4 lg:grid-cols-4">
255	          <KpiCard
256	            title="Total Scans"
257	            value={statsQuery.data?.totalScans ?? 0}
258	            icon={ScanLine}
259	            iconColor="text-indigo-600"
260	            iconBg="bg-indigo-100"
261	          />
262	          <KpiCard
263	            title="Avg Score"
264	            value={statsQuery.data?.avgScore ?? 0}
265	            icon={CheckCircle2}
266	            iconColor="text-green-600"
267	            iconBg="bg-green-100"
268	            suffix="/100"
269	          />
270	          <KpiCard
271	            title="Failed Scans"
272	            value={statsQuery.data?.failedScans ?? 0}
273	            icon={AlertTriangle}
274	            iconColor="text-red-600"
275	            iconBg="bg-red-100"
276	          />
277	          <KpiCard
278	            title="Scans Today"
279	            value={statsQuery.data?.scansToday ?? 0}
280	            icon={Clock}
281	            iconColor="text-sky-600"
282	            iconBg="bg-sky-100"
283	          />
284	        </div>
285	      )}
286	
287	      {/* Filters */}
288	      <div className="flex flex-wrap items-center gap-3">
289	        <div className="relative flex-1 min-w-[220px] max-w-xs">
290	          <Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
291	          <Input
292	            placeholder="Search by URL or user email..."
293	            value={search}
294	            onChange={(e) => { setSearch(e.target.value); setPage(0); }}
295	            className="pl-9"
296	            aria-label="Search scans"
297	          />
298	        </div>
299	
300	        <Select
301	          value={statusFilter}
302	          onValueChange={(v) => {
303	            setStatusFilter(v as ScanStatus | "");
304	            setPage(0);
305	          }}
306	        >
307	          <SelectTrigger className="w-[150px]" aria-label="Filter by status">
308	            <SelectValue placeholder="All statuses" />
309	          </SelectTrigger>
310	          <SelectContent>
311	            {STATUS_OPTIONS.map((opt) => (
312	              <SelectItem key={opt.value} value={opt.value}>
313	                {opt.label}
314	              </SelectItem>
315	            ))}
316	          </SelectContent>
317	        </Select>
318	
319	        {hasFilters && (
320	          <Button
