96	const LS_KEY = "crobot_feature_flags";
97	
98	interface StoredFlags {
99	  values: Record<string, boolean>;
100	  timestamps: Record<string, number>;
101	}
102	
103	function loadFlags(): StoredFlags {
104	  try {
105	    const raw = localStorage.getItem(LS_KEY);
106	    if (!raw) return { values: {}, timestamps: {} };
107	    return JSON.parse(raw) as StoredFlags;
108	  } catch {
109	    return { values: {}, timestamps: {} };
110	  }
111	}
112	
113	function saveFlags(stored: StoredFlags): void {
114	  localStorage.setItem(LS_KEY, JSON.stringify(stored));
115	}
116	
117	function getFlagValue(stored: StoredFlags, key: string, defaultValue: boolean): boolean {
118	  return key in stored.values ? stored.values[key] : defaultValue;
119	}
