168	          </p>
169	        </div>
170	      </div>
171	
172	      {/* Flags by category */}
173	      {categories.map((category) => {
174	        const flags = FLAG_DEFINITIONS.filter((f) => f.category === category);
175	
176	        return (
177	          <Card key={category} className="border-border/50 shadow-soft">
