57	function getWeekLabel(date: Date): string {
58	  // Show the Monday of each week as the label (e.g. "Jun 2")
59	  const day = date.getDay();
60	  const monday = new Date(date);
61	  monday.setDate(date.getDate() - (day === 0 ? 6 : day - 1));
62	  return monday.toLocaleDateString("en-US", { month: "short", day: "numeric" });
63	}
